function startCultivate(){if(playerState==='traveling')return;if(playerState==='bodyTrain')stopBodyTrain();if(playerState==='cultivating')return;playerState='cultivating';expTimer=setInterval(function(){var _cultMult=getCultTotalBonus();var _baseGain=10+getCultivateGainBonus();var _finalGain=Math.floor(_baseGain*(1+getCultivateBonus())*_cultMult);setExp(exp+_finalGain);},10000);regenTimer=setInterval(function(){if(playerHP<playerMaxHP)playerHP=Math.min(playerMaxHP,playerHP+playerMaxHP*0.01);renderMain();cultExp++;if(cultExp>=getCultLvReq()){cultExp-=getCultLvReq();cultLv++;}var _bonusPct=0.01+cultLv*0.01;if(Math.random()<_bonusPct){bonusHP+=1;refreshMaxHP();playerHP=playerMaxHP;showFloatTip($btnCult,'生命+1',3000);}if(Math.random()<_bonusPct){bonusATK+=0.1;showFloatTip($btnCult,'攻击+0.1',3000);}if(Math.random()<_bonusPct){bonusDEF+=0.1;showFloatTip($btnCult,'防御+0.1',3000);}},1000);renderMain();}
function stopCultivate(){if(playerState!=='cultivating')return;playerState='idle';clearInterval(expTimer);expTimer=null;if(regenTimer){clearInterval(regenTimer);regenTimer=null;}renderMain();}
