function findSlot(arr,id){for(var i=0;i<arr.length;i++){if(arr[i].id===id)return i;}return-1;}
function addItem(arr,id,maxSlots,qty){qty=qty||1;var idx=findSlot(arr,id);if(idx>=0){var def=ITEMS[id];if(arr[idx].count+qty<=def.maxStack){arr[idx].count+=qty;checkRecipeUnlock();return true;}}if(arr.length<maxSlots){arr.push({id:id,count:qty});checkRecipeUnlock();return true;}return false;}
function checkRecipeUnlock(){Object.keys(RECIPES).forEach(function(rk){if(unlockedRecipes[rk])return;var r=RECIPES[rk];var _mats=r.materials;if(r.dynamicMats){_mats=[{id:'manualFragment',count:5}];}var allFound=true;for(var i=0;i<_mats.length;i++){if(countItemTotal(_mats[i].id)<1){allFound=false;break;}}if(allFound)unlockedRecipes[rk]=true;});}
function removeOne(arr,id){var idx=findSlot(arr,id);if(idx<0)return false;arr[idx].count-=1;if(arr[idx].count<=0)arr.splice(idx,1);return true;}
function removeItems(arr,id,count){var idx=findSlot(arr,id);if(idx<0)return false;if(arr[idx].count<count)return false;arr[idx].count-=count;if(arr[idx].count<=0)arr.splice(idx,1);return true;}
function countItemTotal(id){var bp=findSlot(backpack,id),wh=findSlot(warehouse,id);return(bp>=0?backpack[bp].count:0)+(wh>=0?warehouse[wh].count:0);}
function removeItemsTotal(id,count){var remaining=count;var bp=findSlot(backpack,id);if(bp>=0){var take=Math.min(remaining,backpack[bp].count);backpack[bp].count-=take;remaining-=take;if(backpack[bp].count<=0)backpack.splice(bp,1);}if(remaining>0){var wh=findSlot(warehouse,id);if(wh>=0){var take=Math.min(remaining,warehouse[wh].count);warehouse[wh].count-=take;remaining-=take;if(warehouse[wh].count<=0)warehouse.splice(wh,1);}}}
function moveItem(from,to,fromIdx,maxTo){if(fromIdx>=from.length)return false;var item=from[fromIdx];if(ITEMS[item.id].special)return false;var ti=findSlot(to,item.id);if(ti>=0){to[ti].count+=item.count;from.splice(fromIdx,1);return true;}if(to.length<maxTo){to.push({id:item.id,count:item.count});from.splice(fromIdx,1);return true;}return false;}
function getEquipEffectDesc(id){if(ITEMS[id]&&ITEMS[id].effectDesc)return ITEMS[id].effectDesc;var rk=null;var keys=Object.keys(RECIPES);for(var i=0;i<keys.length;i++){if(RECIPES[keys[i]].resultId===id){rk=keys[i];break;}}if(!rk)return "";var r=RECIPES[rk],eff=[];if(r.effects.cultivateBonus)eff.push("修为获取+"+Math.round(r.effects.cultivateBonus*100)+"%");if(r.effects.hpMax)eff.push("血量上限+"+r.effects.hpMax);if(r.effects.atk)eff.push("攻击+"+r.effects.atk);if(r.effects.def)eff.push("防御+"+r.effects.def);if(r.effects.rec)eff.push("自然恢复+"+r.effects.rec);if(r.effects.lifestealBonus)eff.push("吸血+"+(r.effects.lifestealBonus*100).toFixed(2)+"%");return eff.join("，");}
