function showModal(opts){var html='<div class="modal-name">'+opts.name+'</div><div class="modal-desc" style="white-space:pre-line">'+opts.desc+'</div>';if(opts.equippable){var _eff=opts.effect||'';if(!_eff){var _iks=Object.keys(ITEMS);for(var _ii=0;_ii<_iks.length;_ii++){if(ITEMS[_iks[_ii]].name===opts.name&&ITEMS[_iks[_ii]].effectDesc){_eff=ITEMS[_iks[_ii]].effectDesc;break;}}}html+='<div class="modal-meta">装备效果：'+(_eff||'无')+'</div>';}if(!opts.equippable)html+='<div class="modal-meta">大小：'+opts.size+'　可堆叠：'+opts.maxStack+'</div>';if(!opts.special&&opts.price!==undefined&&opts.price!==null)html+='<div class="modal-meta">出售价格：'+opts.price+' 铜钱</div>';html+='<div class="modal-btns">';if(opts.btn1)html+='<button class="btn btn-sm" id="mb1">'+opts.btn1+'</button>';if(opts.btn2)html+='<button class="btn btn-sm" id="mb2">'+opts.btn2+'</button>';if(opts.btn3)html+='<button class="btn btn-sm" id="mb3">'+opts.btn3+'</button>';html+='<button class="btn btn-sm" id="mbClose">关闭</button></div>';$modalBox.innerHTML=html;$modalOverlay.classList.add('show');document.getElementById('mbClose').addEventListener('click',closeModal);if(opts.btn1&&opts.on1)document.getElementById('mb1').addEventListener('click',function(){closeModal();opts.on1();});if(opts.btn2&&opts.on2)document.getElementById('mb2').addEventListener('click',function(){closeModal();opts.on2();});if(opts.btn3&&opts.on3)document.getElementById('mb3').addEventListener('click',function(){opts.on3();});if(opts.afterRender)opts.afterRender();}
