function showFloatTip(anchor,text,duration){var old=document.querySelector('.float-tip');if(old)old.remove();var el=document.createElement('div');el.className='float-tip';el.textContent=text;document.body.appendChild(el);var r=anchor.getBoundingClientRect();el.style.cssText='position:fixed;left:50%;transform:translateX(-50%);bottom:'+(window.innerHeight-r.top+6)+'px;background:#333;color:#fff;font-size:12px;padding:6px 12px;border-radius:4px;white-space:nowrap;z-index:999;pointer-events:none;opacity:1;transition:opacity 0.3s';setTimeout(function(){el.style.opacity='0';setTimeout(function(){if(el.parentNode)el.remove();},300);},duration||2000);}

