function renderCraftLevelBar(){var el=document.getElementById("craftLevelBar");if(!el)return;var names={alchemy:"炼丹",accessory:"锻造",manual:"秘籍",cook:"烹饪"};var cat=craftCategory;if(!names[cat]){el.innerHTML="";return;}var cl=craftLevels[cat],rq=getCraftLevelReq(cat);el.innerHTML="<span class=\"attr-label\">"+names[cat]+" Lv."+cl.lv+"</span> <span class=\"attr-val\">"+cl.exp+"/"+rq+"</span>";el.onclick=function(){var old=el.querySelector(".craft-level-tip");if(old){old.remove();return;}var tip=document.createElement("div");tip.className="craft-level-tip";if(cl.lv<=1)tip.textContent="暂无加成";else if(cat==="alchemy"&&cl.lv===2)tip.textContent="5%额外产出";else tip.textContent="效果待补充";el.appendChild(tip);};}
