function renderBodyTrain(){var el=document.getElementById('bodyTrainWrap');if(!el)return;var _si=document.getElementById('stateIndicator');if(_si)_si.textContent=playerState==='bodyTrain'?'练体中':'';var _btargets=[{key:'hp',name:'生命练体',bonus:'+5生命/级'},{key:'atk',name:'攻击练体',bonus:'+1攻击/级'},{key:'def',name:'防御练体',bonus:'+1防御/级'}];var h='<div class="section-title">练体</div>';for(var i=0;i<_btargets.length;i++){var t=_btargets[i],bt=bodyTrain[t.key],req=getBodyTrainReq(t.key),pct=Math.min(100,Math.floor(bt.exp/req*100));var isActive=bodyTrainTarget===t.key&&playerState==='bodyTrain';h+='<div class="recipe-row">';h+='<div class="recipe-slot" style="cursor:default">'+t.name+'</div>';h+='<div class="recipe-info">';h+='<div>'+t.name+' <span class="count">Lv.'+bt.lv+' '+t.bonus+'</span></div>';h+='<div style="display:flex;align-items:center;gap:8px;margin-top:4px">';h+='<div style="flex:1;height:8px;background:#eee;border-radius:4px;overflow:hidden"><div style="height:100%;width:'+pct+'%;background:#4CAF50;border-radius:4px"></div></div>';h+='<span style="font-size:12px;color:#888;white-space:nowrap">'+bt.exp+'/'+req+'</span>';h+='</div></div>';h+='<button class="recipe-btn" data-bt="'+t.key+'" style="'+(isActive?'background:#4CAF50;color:#fff':'')+'">'+(isActive?'练体中...':'开始')+'</button>';h+='</div>';}el.innerHTML=h;el.querySelectorAll('.recipe-btn[data-bt]').forEach(function(btn){btn.addEventListener('click',function(){var key=btn.getAttribute('data-bt');if(playerState==='bodyTrain'&&bodyTrainTarget===key){stopBodyTrain();}else{startBodyTrain(key);}});});}
function startBodyTrain(key){if(playerState==='traveling')return;if(playerState==='bodyTrain'&&bodyTrainTarget===key)return;if(playerState==='cultivating')stopCultivate();stopBodyTrain();playerState='bodyTrain';bodyTrainTarget=key;bodyTrainTimer=setInterval(function(){var bt=bodyTrain[key];bt.exp++;var req=getBodyTrainReq(key);if(bt.exp>=req){bt.exp-=req;bt.lv++;if(key==='hp'){bonusHP+=5;bodyTrainBonusHP+=5;refreshMaxHP();playerHP=playerMaxHP;}else if(key==='atk'){bonusATK+=1;bodyTrainBonusATK+=1;}else if(key==='def'){bonusDEF+=1;bodyTrainBonusDEF+=1;}}renderBodyTrain();saveGame();},5000);renderMain();renderBodyTrain();}
