function doCraft(rk){var r=RECIPES[rk],st=craftStats[rk];if(r.maxCraft&&st.crafted>=r.maxCraft)return;var _mats=r.materials;if(r.dynamicMats){var _count=r.effects&&r.effects.skill==='insight'?Math.floor(5*Math.pow(2,skills.insight||0)):5+st.crafted*5;_mats=[{id:'manualFragment',count:_count}];}for(var i=0;i<_mats.length;i++){var m=_mats[i];if(countItemTotal(m.id)<m.count)return;}for(var i=0;i<_mats.length;i++)removeItemsTotal(_mats[i].id,_mats[i].count);if(r.effects&&r.effects.skill){st.crafted++;var sk=r.effects.skill;skills[sk]=(skills[sk]||0)+1;renderCraft();saveGame();return;}var cat=rk==='herbPill'||rk==='mosquitoPill'||rk==='lingzhiPill'?'alchemy':rk==='grassKnot'||rk==='ratSkinAmulet'?'accessory':rk==='songrongSoup'?'cook':'manual';addCraftExp(cat,1);if(Math.random()<r.successRate){st.crafted++;addItem(warehouse,r.resultId,WAREHOUSE_SLOTS);var extra=cat==='alchemy'&&craftLevels.alchemy.lv>=2&&Math.random()<0.05;if(extra&&(!r.maxCraft||st.crafted<r.maxCraft)){st.crafted++;addItem(warehouse,r.resultId,WAREHOUSE_SLOTS);}}renderCraft();saveGame();}
