function renderDestList(){var h='';Object.keys(DESTS).forEach(function(k){if(isDestUnlocked(k)){h+='<div class="dest-item'+(selectedDest===k?' selected':'')+'" data-dest="'+k+'">'+DESTS[k].name+'</div>';}});$destList.innerHTML=h;}
