function pickWeightedMonster(list){var total=0;for(var i=0;i<list.length;i++)total+=list[i].weight;var r=Math.random()*total,acc=0;for(var i=0;i<list.length;i++){acc+=list[i].weight;if(r<acc)return list[i].key;}return list[0].key;}
function getMapExpReq(lv){return 50*Math.pow(2,lv-1);}
function getMapLv(destId){return mapExp[destId]?mapExp[destId].lv:1;}
function getMapCurExp(destId){return mapExp[destId]?mapExp[destId].exp:0;}
function addMapExp(destId,amount){if(!mapExp[destId])mapExp[destId]={exp:0,lv:1};mapExp[destId].exp+=amount;while(mapExp[destId].exp>=getMapExpReq(mapExp[destId].lv)){mapExp[destId].exp-=getMapExpReq(mapExp[destId].lv);mapExp[destId].lv++;}saveGame();}
function rollVariant(){var r=Math.random();return r<0.01?2:r<0.03?1:0;}
function getVariantSuffix(v){return v===1?'·银灵':v===2?'·金灵':v===3?'·闪灵':'';}
function getVariantMult(v){return v===1?2:v===2?3:v===3?13:1;}
function getVariantDropMult(v){return v===1?3:v===2?5:v===3?33:1;}
function getPostDoneMoves(destId){return (getMapLv(destId)-1)*10;}
function weightedPick(arr){var t=0,i;for(i=0;i<arr.length;i++)t+=arr[i].w;var r=Math.random()*t,a=0;for(i=0;i<arr.length;i++){a+=arr[i].w;if(r<a)return arr[i].v;}return arr[0].v;}function codexAllOwned(){var list=['mosquitoContainer','mosquitoFemaleContainer'];for(var i=0;i<list.length;i++){var id=list[i];if(id==='mosquitoContainer'&&!containerOwned)return false;if(id==='mosquitoFemaleContainer'&&!containerFemaleOwned)return false;}return true;}function randomShopItems(){var _itemDest={lingzhi:'mountain',songrong:'mountain',boarHorn:'mountain'};var mats=[];Object.keys(ITEMS).forEach(function(id){var it=ITEMS[id];if(!it.special&&it.sellPrice!==null&&!it.equippable&&!it.usable&&id!=='mosquitoCorpse'&&id!=='silverShard'&&id!=='goldShard'&&id!=='flashShard'){if(_itemDest[id]&&!isDestUnlocked(_itemDest[id]))return;mats.push({v:id,w:1});}});if(!mats.length)mats.push({v:'herb',w:1});var specials=[];Object.keys(ITEMS).forEach(function(id){var it=ITEMS[id];if(it.special&&((id==='mosquitoContainer'&&!containerOwned)||(id==='mosquitoFemaleContainer'&&!containerFemaleOwned)))specials.push({v:id,w:1});});var pool=[{v:'mat',w:84.5},{v:'faintSpirit',w:13},{v:'manualFragment',w:2},{v:'special',w:specials.length?0.5:0}];var out=[];for(var i=0;i<shopLevel.gridCount;i++){var seg=weightedPick(pool);if(seg==='mat')out.push(weightedPick(mats));else if(seg==='special')out.push(weightedPick(specials));else if(seg==='manualFragment')out.push('manualFragment');else out.push('faintSpirit');}return out;}function refreshShop(now){if(!now)now=Date.now();shopRefreshAt=now+SHOP_REFRESH_MS;var ids=randomShopItems();for(var i=0;i<shopLevel.gridCount;i++){shopSlots[i]=ids[i]?{id:ids[i],count:1}:null;}renderShop();saveGame();}function ensureShop(){var now=Date.now();if(!shopRefreshAt||now>=shopRefreshAt){refreshShop(now);return;}renderShop();}function updateShopCountdown(){var el=document.getElementById('shopCountdown');if(!el)return;if(!shopRefreshAt){el.textContent='已刷新';return;}var rem=Math.max(0,Math.ceil((shopRefreshAt-Date.now())/1000));var m=Math.floor(rem/60);var s2=rem%60;el.textContent=(m<10?'0'+m:''+m)+':'+(s2<10?'0'+s2:''+s2);}function startShopTimer(){if(shopTimer)return;shopTimer=setInterval(function(){if(!document.getElementById('pageShop').classList.contains('active')){clearInterval(shopTimer);shopTimer=null;return;}updateShopCountdown();if(Date.now()>=shopRefreshAt){refreshShop();}},1000);}function getBuyPrice(id){var it=ITEMS[id];if(!it)return 0;if(it.special)return 200;if(id==='mosquitoCorpse')return 0;if(it.sellPrice===null||it.sellPrice===undefined)return 10;return it.sellPrice*2;}
function showShopInfo(){var gc=shopLevel.gridCount;var h='<div class="modal-name">商店信息</div><div class="modal-scroll">';h+='<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid #eee">';h+='<span>商店格子数量：'+gc+'</span>';if(gc<5){var cost=gc===3?200:500;h+='<button class="btn btn-sm" id="btnUpGrid">升级 '+cost+'铜钱</button>';}else h+='<span style="font-size:12px;color:#aaa">已满级</span>';h+='</div>';h+='<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0">';h+='<span>稀有物品概率等级：'+shopLevel.rareLevel+'</span>';h+='<span style="font-size:12px;color:#aaa">暂不可升级</span>';h+='</div>';h+='</div><div class="modal-btns"><button class="btn btn-sm" id="mbClose">关闭</button></div>';$modalBox.innerHTML=h;$modalOverlay.classList.add('show');document.getElementById('mbClose').addEventListener('click',closeModal);var $ug=document.getElementById('btnUpGrid');if($ug)$ug.addEventListener('click',function(){var cost=gc===3?200:500;if(copper<cost){showTip('铜钱不足，无法升级。');return;}setCopper(copper-cost);shopLevel.gridCount++;refreshShop();showShopInfo();});}
function buildTravelInfo(){var d=DESTS[selectedDest],et=travelExplores<0?'无限':travelExplores,done=travelProg>=100,s='前进距离：<span class="val">'+travelDist+'km</span>';if(!inCombat&&!done)s+='　剩余探索：<span class="val">'+et+'</span>';s+='<br><span style="font-size:12px">'+d.name+'</span>';return s;}
