function buildTravelContent(){var d=DESTS[selectedDest],end=travelDist>=d.maxDist,done=travelProg>=100,h='<div class="travel-info">'+buildTravelInfo()+'</div><div class="progress-section"><div class="progress-text">游历进度 <span class="pct">'+travelProg+'%</span></div><div class="progress-bar-outer"><div class="progress-bar-inner" style="width:'+travelProg+'%"></div></div></div><div class="combat-panel" id="combatPanel">'+buildCombatPanel()+'</div><div class="combat-dmg-wrap"><div class="combat-dmg-lines" id="travelTextArea">';for(var i=0;i<travelMsgLines.length;i++)h+='<div>'+travelMsgLines[i]+'</div>';h+='</div>';if(combatRepeat>1)h+='<div class="repeat-badge">x'+combatRepeat+'</div>';h+='</div>';if(!inCombat&&!defeatedInTravel){if(end&&!done)h+='<div class="travel-end-msg">'+d.name+'也就那么大，已经走到头了</div>';if(done){h+='<div class="travel-end-msg">游历完成！</div>';h+='<div style="text-align:center;font-size:12px;color:#999;margin-top:4px">剩余可探索次数：'+(postDoneMoves<0?getPostDoneMoves(selectedDest):Math.max(0,postDoneMoves))+'</div>';}}return h;}
function buildTravelBtns(){var d=DESTS[selectedDest],end=travelDist>=d.maxDist,done=travelProg>=100,h='';var canPost=done&&postDoneMoves>0;if(defeatedInTravel)h+='<button class="travel-btn" style="visibility:hidden">前进</button><button class="travel-btn" style="visibility:hidden">探索</button><button class="travel-btn" id="btnAbn">返回</button>';else if(inCombat){var _stanceNames={balanced:'平衡',desperate:'拼命',cautious:'谨慎'};h+='<button class="travel-btn" id="btnAdv">攻击</button><button class="travel-btn" id="btnStance" style="font-size:12px;margin-top:-42px;align-self:flex-start">'+_stanceNames[stance]+'</button>'+(combatVariant!==3&&!(enemyData&&enemyData.boss)?'<button class="travel-btn" id="btnAbn">逃跑</button>':'<button class="travel-btn" style="visibility:hidden">逃跑</button>');}else{h+='<button class="travel-btn" id="btnExp"'+((!done&&travelExplores===0)||(done&&postDoneMoves<=0)?' style="visibility:hidden"':'')+'>探索</button>';h+='<button class="travel-btn" id="btnAdv"'+((end||(done&&!canPost))?' style="visibility:hidden"':'')+'>前进</button>';h+='<button class="travel-btn" id="btnAbn">返回</button>';}return h;}
function showEventInfo(){var d=DESTS[selectedDest];if(!d)return;var h='<div class="modal-name">事件概率</div>';if(selectedDest==='grassland'){h+='<div class="modal-desc"><b>前进</b><br>怪物 '+Math.round(d.monsterChance*100)+'%　修为 '+d.expMin+'-'+d.expMax+'<br>额外：铜钱 '+Math.round(d.copperChance*100)+'%　商人事件 2%'+(getMapLv('grassland')>=10?'　地域仙灵 3%':'')+'<br><br><b>探索</b><br>怪物 20%　素材 20%　修为 '+d.expMin+'-'+d.expMax+' 60%<br>额外：铜钱 '+Math.round(d.copperChance*100)+'%　商人事件 2%'+(getMapLv('grassland')>=10?'　地域仙灵 3%':'')+'<br><br><b>探索(10km后)</b><br>怪物 20%　素材 20%　修为 5-10 55%　灵气残影 5%<br>额外：铜钱 '+Math.round(d.copperChance*100)+'%　商人事件 2%'+(getMapLv('grassland')>=10?'　地域仙灵 3%':'')+'</div>';}else if(selectedDest==='mountain'){h+='<div class="modal-desc"><b>前进</b><br>怪物 40%　修为 20-30 60%<br><br><b>探索</b><br>怪物 20%　修为 25-30 60%　素材 20%<br>素材：灵芝(权重5)　松茸(权重15)</div>';}else{h+='<div class="modal-desc">暂无事件信息</div>';}h+='<div class="modal-btns"><button class="btn btn-sm" id="mbClose">关闭</button></div>';$modalBox.innerHTML=h;$modalOverlay.classList.add('show');document.getElementById('mbClose').addEventListener('click',closeModal);}function bindTravelBtns(){var d=DESTS[selectedDest],end=travelDist>=d.maxDist,done=travelProg>=100,$a=document.getElementById('btnAdv'),$e=document.getElementById('btnExp'),$b=document.getElementById('btnAbn');if($a&&!defeatedInTravel){if(inCombat)$a.addEventListener('click',doAttack);else if(!end&&!done)$a.addEventListener('click',doAdvance);}if($e&&!defeatedInTravel)$e.addEventListener('click',doExplore);if($b){if(inCombat&&!defeatedInTravel)$b.addEventListener('click',doFlee);else $b.addEventListener('click',doReturn);}var $s=document.getElementById('btnStance');if($s)$s.addEventListener('click',function(){var available=['balanced'];if(stanceProficiency.balanced>=100)available.push('desperate');if(stanceProficiency.desperate>=100)available.push('cautious');var idx=available.indexOf(stance);stance=available[(idx+1)%available.length];renderTravelStatus();saveGame();});}
