function doAdvance(){if(playerState!=='traveling'||inCombat||defeatedInTravel)return;var d=DESTS[selectedDest];if(travelProg>=100&&postDoneMoves<0)postDoneMoves=getPostDoneMoves(selectedDest);if(travelDist>=d.maxDist){if(travelProg>=100&&postDoneMoves>0){postDoneMoves--;renderTravelLower();saveGame();}return;}clearTravelMsg();lastCombatLines=null;combatRepeat=0;travelDist+=1;travelExplores=d.explorePerAdvance;travelProg=Math.min(100,travelProg+d.progressStep);if(travelProg>=100&&postDoneMoves<0)postDoneMoves=getPostDoneMoves(selectedDest);if(travelDist>=d.maxDist)travelExplores=-1;if(Math.random()<d.monsterChance){startCombat(pickWeightedMonster(d.advanceMonsters));return;}var g=Math.floor(Math.random()*(d.expMax-d.expMin+1))+d.expMin;setExp(exp+g);if(selectedDest==='grassland'){if(getMapLv('grassland')>=10&&Math.random()<0.03){startCombat('grassFairy');return;}if(Math.random()<0.02){showMerchantEvent();return;}if(Math.random()<d.copperChance){setCopper(copper+1);setTravelMsg(['修为+'+g,'地上有枚沾灰的铜钱，捡起来吧']);return;}}setTravelMsg(['修为+'+g]);}
